mapper.select:
SELECT COUNT(*)
  FROM SCHED_TRANSFORM_RESULT R
 INNER JOIN SCHED_TRANSFORM_TASK T
    ON R.TRANSFORM_TASK_ID = T.TRANSFORM_TASK_ID
 INNER JOIN SCHED_COLLECT_RAW_DATA D
    ON T.RAW_DATA_ID = D.RAW_DATA_ID
 INNER JOIN SCHED_TRANSFORM_RULE_VERSION V
    ON T.TRANSFORM_RULE_VERSION_ID = V.TRANSFORM_RULE_VERSION_ID
 WHERE D.EXTERNAL_API_ID = #{externalApiId}
   AND V.TRANSFORM_RULE_ID = #{transformRuleId}
   AND V.VERSION_NO = #{versionNo}
   AND R.CREATED_AT  >=  #{startAt}
   AND R.CREATED_AT  <  #{endAt}
